public static class GameRotationPublicationTests {
 static int scenarios,assertions;static long nativeCalls;
 static void Check(bool value,string why){assertions++;if(!value)throw new Exception(why);}
 static void Eq<T>(T a,T b,string why){Check(EqualityComparer<T>.Default.Equals(a,b),why+" expected="+a+" actual="+b);}
 static void Same(object a,object b,string why){Check(Object.ReferenceEquals(a,b),why);}
 static void Near(double a,float b,string why){Check(!Single.IsNaN(b)&&Math.Abs(a-b)<0.000002,why+" expected="+a+" actual="+b);}
 static void Test(string name,Action action){try{action();scenarios++;}catch(Exception e){throw new Exception(name+": "+e.Message,e);}}
 static void Missing(uint at,Action action,string why){try{action();}catch(MissingContract e){Eq(at,e.Address,why+" address");return;}throw new Exception("Expected Unsupported: "+why);}
 static void Unknown<T>(Field<T> field,string why){Missing(0,delegate{field.Read(0);},why);}
 static uint Bits(float x){return BitConverter.ToUInt32(BitConverter.GetBytes(x),0);}
 static NavigationPoint3 Point(float x,float y,float z){var p=new NavigationPoint3();p.X.Write(x);p.Y.Write(y);p.Z.Write(z);return p;}
 static void Box(WorldBounds24 b,float x,float y,float z,float ex,float ey,float ez){b.Center00.Write(x);b.Center04.Write(y);b.Center08.Write(z);b.Extent0C.Write(ex);b.Extent10.Write(ey);b.Extent14.Write(ez);}
