 static void Yaw(EntityCoordinates64 f,double sine,double cosine,string why){double[] e={cosine,0,-sine,0,1,0,sine,0,cosine};for(int n=0;n<9;n++)Near(e[n],f.Basis18[n].Read(0),why+" basis"+n);}
 static void MatrixYaw(GameMovementMatrix48 f,double sine,double cosine,string why){double[] e={cosine,0,-sine,0,1,0,sine,0,cosine,0,0,0};for(int n=0;n<12;n++)Near(e[n],f.At(n,0).Read(0),why+" lane"+n);}
